  ];

  fs.writeFileSync(OUTPUT_LOG_PATH, logLines.join("\n") + "\n", "utf-8");
  console.log(`Summary log written to: ${OUTPUT_LOG_PATH}`);

  console.log("\n=== Summary ===");
  logLines.forEach((line) => console.log(line));
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
